import{_ as i,o as t,c as e,ai as r}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"Mini MES · 项目目标","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/industrial-digitalization/mini-mes/index.md","filePath":"tech-system/industrial-digitalization/mini-mes/index.md"}'),l={name:"tech-system/industrial-digitalization/mini-mes/index.md"};function d(n,a,s,o,h,m){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="mini-mes-·-项目目标" tabindex="-1">Mini MES · 项目目标 <a class="header-anchor" href="#mini-mes-·-项目目标" aria-label="Permalink to “Mini MES · 项目目标”">​</a></h1><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>状态</td><td>🔵 设计中</td></tr><tr><td>对外名</td><td>Industrial Digital Lab / Mini MES V0</td></tr><tr><td>类型</td><td><code>[决策]</code> 产品定义</td></tr><tr><td>GitHub</td><td>暂未开放</td></tr><tr><td>证据</td><td>本文档</td></tr></tbody></table><hr><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to “一句话”">​</a></h2><p>做一个<strong>可持续演进的工业数字化实验项目</strong>：先跑通设备到监控页的最小闭环，再按需引入 MQTT、业务能力与 AI，最终开源到 GitHub。</p><p>不是「完整商业 MES」，也不是「工业数字化教程」。</p><hr><h2 id="要证明什么" tabindex="-1">要证明什么 <a class="header-anchor" href="#要证明什么" aria-label="Permalink to “要证明什么”">​</a></h2><ol><li><strong>Java 全栈</strong>：Gateway / 后端 / 简单前端能串起来</li><li><strong>工业数字化理解</strong>：协议接入、实时状态、业务与测点分离</li><li><strong>工程判断</strong>：知道什么时候该上 MQTT / 时序库 / 微服务，什么时候不该</li></ol><p>以后叠加 AI（告警摘要、知识问答等）也挂在这个项目上，而不是另起炉灶。</p><hr><h2 id="v0-范围-做" tabindex="-1">V0 范围（做） <a class="header-anchor" href="#v0-范围-做" aria-label="Permalink to “V0 范围（做）”">​</a></h2><ul><li>设备模拟（温度 / 压力等）</li><li>Gateway 采集（优先 Modbus TCP 模拟）</li><li>HTTP 上报到 Spring Boot</li><li>MySQL（业务与历史）+ Redis（在线状态 / 最新值）</li><li>Vue：设备列表、在线状态、实时值、简单历史曲线</li></ul><h2 id="v0-明确不做" tabindex="-1">V0 明确不做 <a class="header-anchor" href="#v0-明确不做" aria-label="Permalink to “V0 明确不做”">​</a></h2><ul><li>MQTT / EMQX</li><li>TDengine / 微服务 / K8s</li><li>完整工单、工艺、追溯、OEE</li><li>组态大屏、OPC UA 全协议栈</li></ul><p>理由见 <a href="./../decisions/">判断记录</a>。</p><hr><h2 id="相关页" tabindex="-1">相关页 <a class="header-anchor" href="#相关页" aria-label="Permalink to “相关页”">​</a></h2><ul><li><a href="./architecture.html">架构演进</a></li><li><a href="./roadmap.html">Roadmap</a></li><li><a href="./domain.html">Domain / 问题</a></li></ul>',19)])])}const b=i(l,[["render",d]]);export{p as __pageData,b as default};
